		err = JlTuple.LoadNew(proc, 1, err, out from);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>用通用 socket 连接把任意数据按格式串编码后发出，可指定目标地址；四个形参全是输入。</summary>
	/// <param name="socket">socket 编号。</param>
	/// <param name="format">把数据转换成字节流的规格。Default: "z"</param>
	/// <param name="data">待发送的值或元组。</param>
	/// <param name="to">通信对端的 IP 或主机名与端口。Default: []</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 331。四个输入按形参顺序占槽 0..3，全部经 Store 钉住，转换与发送都在原生侧完成，无输出。</para>
	///   <para><b>何时用静态版</b>与 <see cref="ReceiveData"/> 成对，是门面里唯一能把数据按自定义格式写向 socket 或设备的入口；给 to 传空元组即沿用连接的对端 [待实测]。</para>
	///   <para><b>参数取向</b>零个 out；四个入参各占一槽，调用后逐个解钉。</para>
	///   <para><b>资源与坑</b>format 与 to 的合法取值由原生校验 [待实测]；本方法不改动 data；发送失败由 PostCall 抛错。</para>
	///   <code>
	///   using JLVisionLib;
	///
	///   JlTuple socket = new JlTuple(0);
	///   JlTuple data = new JlTuple(1.0, 2.0, 3.0);
	///   JlOperatorSet.SendData(socket, new JlTuple("z"), data, new JlTuple());
	///   data.Dispose();
	///   socket.Dispose();
	///   </code>
	/// </remarks>
	public static void SendData(JlTuple socket, JlTuple format, JlTuple data, JlTuple to)
	{
		IntPtr proc = JlNativeApi.PreCall(331);
		JlNativeApi.Store(proc, 0, socket);
		JlNativeApi.Store(proc, 1, format);
		JlNativeApi.Store(proc, 2, data);
		JlNativeApi.Store(proc, 3, to);
		int procResult = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(socket);
		JlNativeApi.UnpinTuple(format);
		JlNativeApi.UnpinTuple(data);
		JlNativeApi.UnpinTuple(to);
		JlNativeApi.PostCall(proc, procResult);
	}





















	/// <summary>由两视图点对与两台相机矩阵估计本质矩阵，并顺带重建三维点：七个结果全部走 out 元组。</summary>
	/// <param name="rows1">图 1 点的行坐标。</param>
	/// <param name="cols1">图 1 点的列坐标。</param>
	/// <param name="rows2">图 2 点的行坐标。</param>
	/// <param name="cols2">图 2 点的列坐标。</param>
	/// <param name="covRR1">图 1 点的行坐标方差。Default: []</param>
	/// <param name="covRC1">图 1 点的行/列协方差。Default: []</param>
	/// <param name="covCC1">图 1 点的列坐标方差。Default: []</param>
	/// <param name="covRR2">图 2 点的行坐标方差。Default: []</param>
	/// <param name="covRC2">图 2 点的行/列协方差。Default: []</param>
	/// <param name="covCC2">图 2 点的列坐标方差。Default: []</param>
	/// <param name="camMat1">第一台相机的矩阵。</param>
	/// <param name="camMat2">第二台相机的矩阵。</param>
