	/// <param name="EMatrix">计算得到的本质矩阵。</param>
	/// <param name="covEMat">本质矩阵的 9x9 协方差矩阵。</param>
	/// <param name="error">极线距离误差的均方根。</param>
	/// <param name="x">重建三维点的 X 坐标。</param>
	/// <param name="y">重建三维点的 Y 坐标。</param>
	/// <param name="z">重建三维点的 Z 坐标。</param>
	/// <param name="covXYZ">重建三维点的协方差矩阵。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 352。十三个输入严格同序占槽 0..10 之后接两台相机矩阵与算法串（槽 10、11、12），七路输出全部声明为对象输出并以 DOUBLE 型 LoadNew 装载：矩阵、其协方差、误差、三个点坐标分量、点的协方差。</para>
	///   <para><b>与实例重载的取舍</b><see cref="JlHomMat2D.VectorToEssentialMatrix(JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlTuple, JlHomMat2D, string, out JlTuple, out JlTuple, out JlTuple, out JlTuple, out JlTuple, out JlTuple)"/> 把本实例充当第一台相机矩阵、本质矩阵走返回的新实例，其余走 out；本静态版两台相机矩阵都是普通输入元组，谁都不被覆写，代价是七个 out 要逐个判型与释放。相机矩阵已以 JlHomMat2D 存在时用实例版更自然。</para>
	///   <para><b>参数取向</b>七个 out，装载顺序即形参顺序；六个协差参数空元组即等权，非空按点逐元素配对。</para>
	///   <para><b>资源与坑</b>误差与协方差的维度约定 [待实测]；重建点的尺度由相机基线决定，无基线信息时结果退化；七个 out 元组用完 Dispose。</para>
	/// </remarks>
	public static void VectorToEssentialMatrix(JlTuple rows1, JlTuple cols1, JlTuple rows2, JlTuple cols2, JlTuple covRR1, JlTuple covRC1, JlTuple covCC1, JlTuple covRR2, JlTuple covRC2, JlTuple covCC2, JlTuple camMat1, JlTuple camMat2, JlTuple method, out JlTuple EMatrix, out JlTuple covEMat, out JlTuple error, out JlTuple x, out JlTuple y, out JlTuple z, out JlTuple covXYZ)
	{
		IntPtr proc = JlNativeApi.PreCall(352);
		JlNativeApi.Store(proc, 0, rows1);
		JlNativeApi.Store(proc, 1, cols1);
		JlNativeApi.Store(proc, 2, rows2);
		JlNativeApi.Store(proc, 3, cols2);
		JlNativeApi.Store(proc, 4, covRR1);
		JlNativeApi.Store(proc, 5, covRC1);
		JlNativeApi.Store(proc, 6, covCC1);
		JlNativeApi.Store(proc, 7, covRR2);
		JlNativeApi.Store(proc, 8, covRC2);
		JlNativeApi.Store(proc, 9, covCC2);
		JlNativeApi.Store(proc, 10, camMat1);
		JlNativeApi.Store(proc, 11, camMat2);
		JlNativeApi.Store(proc, 12, method);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		JlNativeApi.InitOCT(proc, 3);
		JlNativeApi.InitOCT(proc, 4);
		JlNativeApi.InitOCT(proc, 5);
		JlNativeApi.InitOCT(proc, 6);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(rows1);
		JlNativeApi.UnpinTuple(cols1);
		JlNativeApi.UnpinTuple(rows2);
		JlNativeApi.UnpinTuple(cols2);
		JlNativeApi.UnpinTuple(covRR1);
		JlNativeApi.UnpinTuple(covRC1);
		JlNativeApi.UnpinTuple(covCC1);
		JlNativeApi.UnpinTuple(covRR2);
		JlNativeApi.UnpinTuple(covRC2);
		JlNativeApi.UnpinTuple(covCC2);
		JlNativeApi.UnpinTuple(camMat1);
		JlNativeApi.UnpinTuple(camMat2);
		JlNativeApi.UnpinTuple(method);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out EMatrix);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out covEMat);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out error);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.DOUBLE, err, out x);
		err = JlTuple.LoadNew(proc, 4, JlTupleType.DOUBLE, err, out y);
		err = JlTuple.LoadNew(proc, 5, JlTupleType.DOUBLE, err, out z);
		err = JlTuple.LoadNew(proc, 6, JlTupleType.DOUBLE, err, out covXYZ);
		JlNativeApi.PostCall(proc, err);
	}




	/// <summary>对两幅图自动灰值匹配特征点并用 RANSAC 估本质矩阵，矩阵、协方差、误差与内点索引五路结果全走 out。</summary>
	/// <param name="image1">输入图像 1。</param>
	/// <param name="image2">输入图像 2。</param>
	/// <param name="rows1">图 1 特征点的行坐标。</param>
	/// <param name="cols1">图 1 特征点的列坐标。</param>
	/// <param name="rows2">图 2 特征点的行坐标。</param>
	/// <param name="cols2">图 2 特征点的列坐标。</param>
	/// <param name="camMat1">第一台相机的矩阵。</param>
	/// <param name="camMat2">第二台相机的矩阵。</param>
	/// <param name="grayMatchMethod">灰值比较度量。Default: "ssd"</param>
	/// <param name="maskSize">灰值模板尺寸。Default: 10</param>
	/// <param name="rowMove">对应点行坐标的平均偏移。Default: 0</param>
	/// <param name="colMove">对应点列坐标的平均偏移。Default: 0</param>
	/// <param name="rowTolerance">匹配搜索窗口的半高。Default: 200</param>
	/// <param name="colTolerance">匹配搜索窗口的半宽。Default: 200</param>
	/// <param name="rotation">右图相对左图朝向的估计值。Default: 0.0</param>
	/// <param name="matchThreshold">灰值匹配阈值。Default: 10</param>
	/// <param name="estimationMethod">本质矩阵算法与特殊相机朝向的处理。Default: "normalized_dlt"</param>
	/// <param name="distanceThreshold">点到对应极线的最大偏差。Default: 1</param>
	/// <param name="randSeed">随机数生成器种子。Default: 0</param>
	/// <param name="EMatrix">计算得到的本质矩阵。</param>
	/// <param name="covEMat">本质矩阵的 9x9 协方差矩阵。</param>
	/// <param name="error">极线距离误差的均方根。</param>
	/// <param name="points1">图 1 中匹配成功的输入点索引。</param>
	/// <param name="points2">图 2 中匹配成功的输入点索引。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 356。图像走对象通道：image1 写入 1 号槽、image2 写入 2 号槽，随后 rows1 写控制槽 0、cols1 又写 1 号、rows2 写 2 号——图标号与控制标号各自独立，因此 C# 形参顺序不能与槽号简单对照。输出五路：前三路 DOUBLE 型元组，后两路以 INTEGER 型装载的索引。</para>
	///   <para><b>与实例重载的取舍</b><see cref="JlImage.MatchEssentialMatrixRansac(JlImage, JlTuple, JlTuple, JlTuple, JlTuple, JlHomMat2D, JlHomMat2D, string, int, int, int, int, int, JlTuple, JlTuple, string, JlTuple, int, out JlTuple, out JlTuple, out JlTuple, out JlTuple)"/> 以 this 作 image1、image2 为 JlImage 形参、本质矩阵走返回的新实例，且把匹配参数摊成 int/double/string 标量；本静态版能吃裸 JlObject 句柄、参数一律元组化，并且连本质矩阵本身也走 out，适合两侧图像是别处算子直接产出的句柄、或需要元组形态参数的场合。</para>
	///   <para><b>参数取向</b>五个 out；points1 与 points2 是输入点数组里的下标而非坐标，用于回取内点对。随机种子取零时结果可复现，非零为随机 [待实测]。</para>
	///   <para><b>资源与坑</b>两张图像在原生调用结束前由 KeepAlive 保住，调用方不必干预；五个 out 元组用完 Dispose；RANSAC 有随机性，同一输入重复调用结果可能不同 [待实测]。</para>
	/// </remarks>
	public static void MatchEssentialMatrixRansac(JlObject image1, JlObject image2, JlTuple rows1, JlTuple cols1, JlTuple rows2, JlTuple cols2, JlTuple camMat1, JlTuple camMat2, JlTuple grayMatchMethod, JlTuple maskSize, JlTuple rowMove, JlTuple colMove, JlTuple rowTolerance, JlTuple colTolerance, JlTuple rotation, JlTuple matchThreshold, JlTuple estimationMethod, JlTuple distanceThreshold, JlTuple randSeed, out JlTuple EMatrix, out JlTuple covEMat, out JlTuple error, out JlTuple points1, out JlTuple points2)
	{
		IntPtr proc = JlNativeApi.PreCall(356);
		JlNativeApi.Store(proc, 1, image1);
		JlNativeApi.Store(proc, 2, image2);
		JlNativeApi.Store(proc, 0, rows1);
		JlNativeApi.Store(proc, 1, cols1);
		JlNativeApi.Store(proc, 2, rows2);
		JlNativeApi.Store(proc, 3, cols2);
		JlNativeApi.Store(proc, 4, camMat1);
		JlNativeApi.Store(proc, 5, camMat2);
		JlNativeApi.Store(proc, 6, grayMatchMethod);
		JlNativeApi.Store(proc, 7, maskSize);
		JlNativeApi.Store(proc, 8, rowMove);
		JlNativeApi.Store(proc, 9, colMove);
		JlNativeApi.Store(proc, 10, rowTolerance);
		JlNativeApi.Store(proc, 11, colTolerance);
		JlNativeApi.Store(proc, 12, rotation);
		JlNativeApi.Store(proc, 13, matchThreshold);
		JlNativeApi.Store(proc, 14, estimationMethod);
		JlNativeApi.Store(proc, 15, distanceThreshold);
		JlNativeApi.Store(proc, 16, randSeed);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		JlNativeApi.InitOCT(proc, 3);
		JlNativeApi.InitOCT(proc, 4);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(rows1);
		JlNativeApi.UnpinTuple(cols1);
		JlNativeApi.UnpinTuple(rows2);
		JlNativeApi.UnpinTuple(cols2);
		JlNativeApi.UnpinTuple(camMat1);
		JlNativeApi.UnpinTuple(camMat2);
		JlNativeApi.UnpinTuple(grayMatchMethod);
		JlNativeApi.UnpinTuple(maskSize);
		JlNativeApi.UnpinTuple(rowMove);
		JlNativeApi.UnpinTuple(colMove);
		JlNativeApi.UnpinTuple(rowTolerance);
		JlNativeApi.UnpinTuple(colTolerance);
		JlNativeApi.UnpinTuple(rotation);
		JlNativeApi.UnpinTuple(matchThreshold);
		JlNativeApi.UnpinTuple(estimationMethod);
		JlNativeApi.UnpinTuple(distanceThreshold);
		JlNativeApi.UnpinTuple(randSeed);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out EMatrix);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out covEMat);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out error);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.INTEGER, err, out points1);
		err = JlTuple.LoadNew(proc, 4, JlTupleType.INTEGER, err, out points2);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image1);
		GC.KeepAlive(image2);
	}































	/// <summary>按给定光照方向对高度场做明暗渲染，渲染结果以全新裸句柄经 out 交付。</summary>
