	{
		IntPtr proc = JlNativeApi.PreCall(431);
		JlNativeApi.Store(proc, 1, imageCol);
		JlNativeApi.Store(proc, 2, imageRow);
		JlNativeApi.Store(proc, 3, featureSpace);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		err = JlObject.LoadNew(proc, 1, err, out regionClass2Dim);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(imageCol);
		GC.KeepAlive(imageRow);
		GC.KeepAlive(featureSpace);
	}

	/// <summary>对两幅图构成的二维特征做无监督聚类分割，类区域以新句柄经 out 返回。</summary>
	/// <param name="image1">第一幅输入图像。</param>
	/// <param name="image2">第二幅输入图像。</param>
	/// <param name="classes">分类结果（新句柄）。</param>
	/// <param name="threshold">到聚类中心的最大距离容差。Default: 15</param>
	/// <param name="numClasses">类别数（聚类中心数）。Default: 5</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 432。不需要样板区域：按 <paramref name="numClasses"/> 个聚类中心与距离容差 <paramref name="threshold"/> 把二维特征平面上的像素自动归堆。</para>
	///   <para><b>与实例重载的取舍</b>见 <see cref="JlImage.Class2dimUnsup(JlImage,int,int)"/>：实例版把两个数值参数钉成 <c>int</c>（<c>StoreI</c>），给不出实数容差；本静态版走通用 <c>Store</c>，按整数还是实数解释取决于传入 <see cref="JlTuple"/> 的元素类型。</para>
	///   <para><b>参数取向</b><paramref name="threshold"/> 与 <paramref name="numClasses"/> 依次占控制槽 0、1，与 C# 形参序一致；单路图标输出由 <c>LoadNew</c> 装入。</para>
	///   <para><b>资源与坑</b><paramref name="classes"/> 是裸 <see cref="JlObject"/> 新句柄，要判型并 <c>Dispose</c>；两图尺寸需一致 [待实测]；聚类中心由数据决定，同图重跑时类别归属是否稳定 [待实测]；<c>GC.KeepAlive</c> 同时保活两幅输入。</para>
	/// </remarks>
	public static void Class2dimUnsup(JlObject image1, JlObject image2, out JlObject classes, JlTuple threshold, JlTuple numClasses)
	{
		IntPtr proc = JlNativeApi.PreCall(432);
		JlNativeApi.Store(proc, 1, image1);
		JlNativeApi.Store(proc, 2, image2);
		JlNativeApi.Store(proc, 0, threshold);
		JlNativeApi.Store(proc, 1, numClasses);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(threshold);
		JlNativeApi.UnpinTuple(numClasses);
		err = JlObject.LoadNew(proc, 1, err, out classes);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image1);
		GC.KeepAlive(image2);
	}

	/// <summary>把输入图与参考图逐像素比对，按模式回传"相似"或"不同"的像素集合（区域），结果以新句柄经 out 返回。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="pattern">用于比对的参考图像。</param>
	/// <param name="selected">两图相似或不同的点（新句柄）。</param>
	/// <param name="mode">返回相似还是不同的像素。Default: "diff_outside"</param>
	/// <param name="diffLowerBound">允许的灰度差下限。Default: -5</param>
	/// <param name="diffUpperBound">允许的灰度差上限。Default: 5</param>
	/// <param name="grayOffset">先从输入图减去的偏移灰度值。Default: 0</param>
	/// <param name="addRow">参考图在行方向的平移量。Default: 0</param>
	/// <param name="addCol">参考图在列方向的平移量。Default: 0</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 433。差值落在 <paramref name="diffLowerBound"/> 与 <paramref name="diffUpperBound"/> 之间算容差内；<paramref name="grayOffset"/> 先从输入图整体减去一个常量，<paramref name="addRow"/> 与 <paramref name="addCol"/> 把参考图平移后再比，用于整幅亮度漂移与轻微套准偏差。</para>
	///   <para><b>与实例重载的取舍</b>见 <see cref="JlImage.CheckDifference(JlImage,string,int,int,int,int,int)"/>：实例版用 <c>StoreS</c> 与 <c>StoreI</c>，五个数值只能取整数；本静态版全部走通用 <c>Store</c>，元组里放实数即可传实数偏移。</para>
	///   <para><b>参数取向</b>控制槽 0 至 5 与 C# 形参序一致；单路图标输出（<c>InitOCT</c> 槽 1 加 <c>LoadNew</c>）。</para>
	///   <para><b>资源与坑</b><paramref name="selected"/> 常是散点区域，下游一般先 <c>Connection</c> 再筛形；两图尺寸不一致时的比对范围与越界像素处理 [待实测]；两路输入均由 <c>GC.KeepAlive</c> 保活，新句柄需 <c>Dispose</c>。</para>
	/// </remarks>
	public static void CheckDifference(JlObject image, JlObject pattern, out JlObject selected, JlTuple mode, JlTuple diffLowerBound, JlTuple diffUpperBound, JlTuple grayOffset, JlTuple addRow, JlTuple addCol)
	{
		IntPtr proc = JlNativeApi.PreCall(433);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 2, pattern);
		JlNativeApi.Store(proc, 0, mode);
		JlNativeApi.Store(proc, 1, diffLowerBound);
		JlNativeApi.Store(proc, 2, diffUpperBound);
		JlNativeApi.Store(proc, 3, grayOffset);
		JlNativeApi.Store(proc, 4, addRow);
		JlNativeApi.Store(proc, 5, addCol);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(mode);
		JlNativeApi.UnpinTuple(diffLowerBound);
		JlNativeApi.UnpinTuple(diffUpperBound);
		JlNativeApi.UnpinTuple(grayOffset);
		JlNativeApi.UnpinTuple(addRow);
		JlNativeApi.UnpinTuple(addCol);
		err = JlObject.LoadNew(proc, 1, err, out selected);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
		GC.KeepAlive(pattern);
	}

	/// <summary>面向字符提取的直方图阈值分割：暗区（字符）与实际所用阈值分别经两路 out 返回。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="histoRegion">在其内统计直方图的区域。</param>
	/// <param name="characters">暗于阈值的区域，即字符（新句柄）。</param>
	/// <param name="sigma">直方图高斯平滑量。Default: 2.0</param>
	/// <param name="percent">灰度差取分位数的百分比。Default: 95</param>
	/// <param name="threshold">回传：本次实际算出的阈值。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 434。在 <paramref name="histoRegion"/> 内取直方图、按 <paramref name="sigma"/> 做高斯平滑，再用 <paramref name="percent"/> 定出字符与背景的分割点，输出暗侧区域。</para>
	///   <para><b>与实例重载的取舍</b>见 <see cref="JlImage.CharThreshold(JlRegion,double,JlTuple,out JlTuple)"/> 与 <see cref="JlImage.CharThreshold(JlRegion,double,double,out int)"/>：实例版把 <paramref name="sigma"/> 钉成 <c>double</c>；本静态版两个数值参数都是 <see cref="JlTuple"/>，且区域与阈值一次全部经 out 交出，便于同时拿裸句柄和原始阈值元组。</para>
	///   <para><b>参数取向</b>两次 <c>InitOCT</c>：槽 1 是图标输出、槽 0 是控制输出；阈值用 <c>JlTuple.LoadNew</c> 显式按 <c>INTEGER</c> 装载，小数部分不保留——这与 <see cref="JlOperatorSet.BinaryThreshold(JlObject,out JlObject,JlTuple,JlTuple,out JlTuple)"/> 不指定类型、按原生类型原样装载的做法不同。</para>
	///   <para><b>资源与坑</b>两个结果都必须写成 <c>out</c>；<paramref name="characters"/> 是新句柄需 <c>Dispose</c>，<paramref name="threshold"/> 是 <see cref="JlTuple"/> 不需释放；<paramref name="histoRegion"/> 只含背景或含干扰图形时阈值会整体偏掉 [待实测：直方图双峰不明显时报错还是给出可用值]；两路输入由 <c>GC.KeepAlive</c> 保活。</para>
	/// </remarks>
	public static void CharThreshold(JlObject image, JlObject histoRegion, out JlObject characters, JlTuple sigma, JlTuple percent, out JlTuple threshold)
	{
		IntPtr proc = JlNativeApi.PreCall(434);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 2, histoRegion);
		JlNativeApi.Store(proc, 0, sigma);
		JlNativeApi.Store(proc, 1, percent);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 0);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(sigma);
		JlNativeApi.UnpinTuple(percent);
		err = JlObject.LoadNew(proc, 1, err, out characters);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.INTEGER, err, out threshold);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
		GC.KeepAlive(histoRegion);
	}

	/// <summary>把标签图按取值拆分，同一灰度值的像素合成一块区域，区域数组以新句柄经 out 返回。</summary>
	/// <param name="labelImage">标签图像。</param>
