		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, method);
		JlNativeApi.Store(proc, 1, lightDark);
		JlNativeApi.Store(proc, 2, genParamName);
		JlNativeApi.Store(proc, 3, genParamValue);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(method);
		JlNativeApi.UnpinTuple(lightDark);
		JlNativeApi.UnpinTuple(genParamName);
		JlNativeApi.UnpinTuple(genParamValue);
		err = JlObject.LoadNew(proc, 1, err, out region);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>按局部均值与标准差自适应阈值分割，结果区域以新句柄经 out 返回。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="region">分割出的区域（新句柄）。</param>
	/// <param name="maskWidth">计算均值与标准差的窗口宽。Default: 15</param>
	/// <param name="maskHeight">计算均值与标准差的窗口高。Default: 15</param>
	/// <param name="stdDevScale">局部标准差的加权系数。Default: 0.2</param>
	/// <param name="absThreshold">与局部均值的最小灰度差。Default: 2</param>
	/// <param name="lightDark">取亮区还是暗区。Default: "dark"</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 441。逐像素用窗内均值加 <paramref name="stdDevScale"/> 倍标准差作为局部阈值，并要求与均值的差不小于 <paramref name="absThreshold"/>，再按 <paramref name="lightDark"/> 取舍，适合光照不均的字符与缺陷图。</para>
	///   <para><b>与实例重载的取舍</b>见 <see cref="JlImage.VarThreshold(int,int,JlTuple,JlTuple,string)"/> 与 <see cref="JlImage.VarThreshold(int,int,double,double,string)"/>（后者的两个阈值参数用 <c>StoreD</c> 直写单值）；本静态版连 <paramref name="maskWidth"/>、<paramref name="maskHeight"/> 也是 <see cref="JlTuple"/>，五个参数一律通用 <c>Store</c>。</para>
	///   <para><b>参数取向</b>控制槽 0 至 4 与 C# 形参序一致；单路图标输出。</para>
	///   <para><b>资源与坑</b>窗口越大越慢，且窗口与笔画宽度相当时会把目标本身吞进均值里而漏检 [待实测：具体漏检阈值与纹理周期关系]；<paramref name="lightDark"/> 非托管层校验，非法字面量由原生报错；新句柄需 <c>Dispose</c>。</para>
	/// </remarks>
	public static void VarThreshold(JlObject image, out JlObject region, JlTuple maskWidth, JlTuple maskHeight, JlTuple stdDevScale, JlTuple absThreshold, JlTuple lightDark)
	{
		IntPtr proc = JlNativeApi.PreCall(441);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, maskWidth);
		JlNativeApi.Store(proc, 1, maskHeight);
		JlNativeApi.Store(proc, 2, stdDevScale);
		JlNativeApi.Store(proc, 3, absThreshold);
		JlNativeApi.Store(proc, 4, lightDark);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(maskWidth);
		JlNativeApi.UnpinTuple(maskHeight);
		JlNativeApi.UnpinTuple(stdDevScale);
		JlNativeApi.UnpinTuple(absThreshold);
		JlNativeApi.UnpinTuple(lightDark);
		err = JlObject.LoadNew(proc, 1, err, out region);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>用另一幅图逐像素当阈值做分割（动态阈值），结果区域以新句柄经 out 返回。</summary>
	/// <param name="origImage">输入图像。</param>
	/// <param name="thresholdImage">逐像素提供局部阈值的图像。</param>
	/// <param name="regionDynThresh">分割出的区域（新句柄）。</param>
	/// <param name="offset">叠加在阈值图上的偏移量。Default: 5.0</param>
	/// <param name="lightDark">取亮于、暗于还是近似等于阈值的像素。Default: "light"</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 442。把 <paramref name="thresholdImage"/> 当逐像素阈值面（常用 <c>GaussImage</c> 或 <c>MedianImage</c> 的低通结果得到），<paramref name="offset"/> 整体抬高或压低该面，<paramref name="lightDark"/> 决定比它亮、比它暗还是两者皆可。</para>
	///   <para><b>与实例重载的取舍</b>见 <see cref="JlImage.DynThreshold(JlImage,double,string)"/>（<c>StoreD</c> 直写单值偏移）与 <see cref="JlImage.DynThreshold(JlImage,JlTuple,string)"/>（元组版）；本静态版 <paramref name="offset"/> 走通用 <c>Store</c>，两幅图都是显式图标入参。</para>
	///   <para><b>参数取向</b>图标输入槽 1、2 分别是原图与阈值图，控制槽 0、1 是偏移与模式；单路图标输出。</para>
	///   <para><b>资源与坑</b>两幅图尺寸需一致，逐像素配对才成立 [待实测：不一致时报错还是按交集处理]；阈值图本身含噪声会导致边缘毛糙，宜先平滑；新句柄需 <c>Dispose</c>，两输入由 <c>GC.KeepAlive</c> 保活。</para>
	/// </remarks>
	public static void DynThreshold(JlObject origImage, JlObject thresholdImage, out JlObject regionDynThresh, JlTuple offset, JlTuple lightDark)
	{
		IntPtr proc = JlNativeApi.PreCall(442);
		JlNativeApi.Store(proc, 1, origImage);
		JlNativeApi.Store(proc, 2, thresholdImage);
		JlNativeApi.Store(proc, 0, offset);
		JlNativeApi.Store(proc, 1, lightDark);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(offset);
		JlNativeApi.UnpinTuple(lightDark);
		err = JlObject.LoadNew(proc, 1, err, out regionDynThresh);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(origImage);
		GC.KeepAlive(thresholdImage);
	}

	/// <summary>按灰度区间做全局阈值分割；本门面版用元组传界，因此能表达特殊量程值与多区间，结果区域经 out 返回。</summary>
