		err = JlObject.LoadNew(proc, 1, err, out basins);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>一次算出盆地与盆地之间的分水线，两路区域各自经一路 out 返回（本门面版没有返回值）。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="basins">分割出的盆地（新句柄）。</param>
	/// <param name="watersheds">盆地之间的分水线（新句柄）。</param>
