		JlNativeApi.Store(proc, 4, alignment);
		JlNativeApi.Store(proc, 5, type);
		JlNativeApi.Store(proc, 6, imageWidth);
		JlNativeApi.Store(proc, 7, imageHeight);
		JlNativeApi.Store(proc, 8, startRow);
		JlNativeApi.Store(proc, 9, startColumn);
		JlNativeApi.Store(proc, 10, bitsPerChannel);
