		JlNativeApi.InitOCT(proc, 0);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(fileName);
		err = JlTuple.LoadNew(proc, 0, err, out OCVHandle);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>把 OCV 工具保存到文件，无 out 输出。</summary>
	/// <param name="OCVHandle">要写出的 OCV 工具句柄。</param>
	/// <param name="fileName">保存的目标文件名。Default: "test_ocv"</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 628。实现把 OCVHandle Store 到参数 0、fileName Store 到参数 1 后 CallProcedure，无 InitOCT/LoadNew，即不产任何句柄。</para>
	///   <para><b>何时用静态版</b>本算子无托管实例双胞胎（B 档），把内存中的 OCV 模板落盘持久化用静态门面。</para>
	///   <para><b>参数取向</b>out 0 个；两入参调用前固定、调用后解固定。</para>
	///   <para><b>资源与坑</b>不会释放 OCVHandle，写盘后仍需自行 CloseOcv；OCVHandle 已失效或句柄类型不符时的行为 [待实测]。</para>
	///   <code>
	///   JlOperatorSet.ReadOcv("test_ocv", out JlTuple ocvHandle);
	///   JlOperatorSet.WriteOcv(ocvHandle, "test_ocv.bak");
	///   JlOperatorSet.CloseOcv(ocvHandle);
	///   </code>
	/// </remarks>
	public static void WriteOcv(JlTuple OCVHandle, JlTuple fileName)
	{
		IntPtr proc = JlNativeApi.PreCall(628);
		JlNativeApi.Store(proc, 0, OCVHandle);
		JlNativeApi.Store(proc, 1, fileName);
		int procResult = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(OCVHandle);
		JlNativeApi.UnpinTuple(fileName);
		JlNativeApi.PostCall(proc, procResult);
	}

	/// <summary>释放一个 OCV 工具句柄占用的资源，无 out 输出。</summary>
	/// <param name="OCVHandle">要释放的 OCV 工具句柄。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 629。实现把 OCVHandle Store 到参数 0 后 CallProcedure，让原生侧回收该 OCV 工具，是 ReadOcv/DeserializeOcv 所得句柄的配对释放算子。</para>
	///   <para><b>何时用静态版</b>本算子无托管实例双胞胎（B 档），凡拿到 JlTuple 形态的 OCV 句柄都须用本算子显式关闭。</para>
	///   <para><b>参数取向</b>out 0 个；入参调用前固定、调用后解固定。</para>
	///   <para><b>资源与坑</b>对同一句柄重复 CloseOcv 或对已失效句柄关闭的行为 [待实测]；Close 后不得再把该句柄传回任何 OCV 算子。</para>
	///   <code>
	///   JlOperatorSet.ReadOcv("test_ocv", out JlTuple ocvHandle);
	///   JlOperatorSet.CloseOcv(ocvHandle);
	///   </code>
	/// </remarks>
	public static void CloseOcv(JlTuple OCVHandle)
	{
		IntPtr proc = JlNativeApi.PreCall(629);
		JlNativeApi.Store(proc, 0, OCVHandle);
		int procResult = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(OCVHandle);
		JlNativeApi.PostCall(proc, procResult);
	}










































































	/// <summary>按相对位置对区域集排序，排序结果以 out 裸句柄返回。</summary>
	/// <param name="regions">待排序的区域。</param>
	/// <param name="sortedRegions">排序后的区域。</param>
	/// <param name="sortMode">排序依据的种类。Default: "first_point"</param>
	/// <param name="order">升序或降序。Default: "true"</param>
	/// <param name="rowOrCol">先行后列或先列后行。Default: "row"</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 703。实现把 regions Store 到参数 1、三个 control 参数 Store 到 0/1/2，经 InitOCT(1)+LoadNew 产出新句柄。</para>
	///   <para><b>与实例重载的取舍</b>JlRegion 同名重载仍是模板注释。本静态版以新裸句柄交回排序结果；注意原生序 control 参数（sortMode/order/rowOrCol）在前、iconic 输入在后，与 C# 形参序 (regions, ..., out) 不同。</para>
	///   <para><b>参数取向</b>out 1 裸句柄；三个字符串/标志参数透传，输入 regions 经 GC.KeepAlive 保活。</para>
	///   <para><b>资源与坑</b>新句柄须释放；sortMode 拼错不在托管层拦截 [待实测可选字面量]。</para>
	/// </remarks>
	public static void SortRegion(JlObject regions, out JlObject sortedRegions, JlTuple sortMode, JlTuple order, JlTuple rowOrCol)
	{
		IntPtr proc = JlNativeApi.PreCall(703);
		JlNativeApi.Store(proc, 1, regions);
		JlNativeApi.Store(proc, 0, sortMode);
		JlNativeApi.Store(proc, 1, order);
		JlNativeApi.Store(proc, 2, rowOrCol);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(sortMode);
		JlNativeApi.UnpinTuple(order);
		JlNativeApi.UnpinTuple(rowOrCol);
