	public static void ReadGraySe(out JlObject SE, JlTuple fileName)
	{
		IntPtr proc = JlNativeApi.PreCall(765);
		JlNativeApi.Store(proc, 0, fileName);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(fileName);
		err = JlObject.LoadNew(proc, 1, err, out SE);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>生成帽状（椭球/圆盘）灰度结构元，作为新图像句柄经 out 返回。</summary>
	/// <param name="SE">生成的结构元（图像句柄）。</param>
	/// <param name="type">像素类型。Default: "byte"</param>
	/// <param name="width">结构元宽度。Default: 5</param>
	/// <param name="height">结构元高度。Default: 5</param>
	/// <param name="smax">结构元中心最大灰度值。Default: 0</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生 id 766。生成中心 smax、边缘 0 的帽状灰度 SE，供 GrayOpening/GrayTophat/GrayBothat 等灰度形态学使用。smax=0 即平顶 SE，灰度形态学退化为只看形状不看高度。</para>
	///   <para><b>与实例重载的取舍</b>静态版用 LoadNew 产出【新句柄】从 out 返回；JlImage.GenDiscSe 实例方法是先 Dispose 再 Load【原地改写 this】（见 <see cref="JlImage"/>）。且实例标量版用 StoreD 直写 smax、无元组钉住开销，而本静态版把 type/width/height/smax 全作 JlTuple 控制参数钉住、可传多值一次生成一批 SE。</para>
	///   <para><b>参数取向</b>1 路对象输出（LoadNew proc1）。type/width/height/smax 占控制槽 0/1/2/3，全部 UnpinTuple；无 iconic 输入。</para>
	///   <para><b>资源与坑</b>SE 是新句柄需释放。帽高大于待测峰高时顶帽会把目标整体当背景吃掉（详见 GrayTophat 的 SE 取法）。</para>
	/// </remarks>
	public static void GenDiscSe(out JlObject SE, JlTuple type, JlTuple width, JlTuple height, JlTuple smax)
	{
		IntPtr proc = JlNativeApi.PreCall(766);
		JlNativeApi.Store(proc, 0, type);
		JlNativeApi.Store(proc, 1, width);
		JlNativeApi.Store(proc, 2, height);
		JlNativeApi.Store(proc, 3, smax);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(type);
		JlNativeApi.UnpinTuple(width);
		JlNativeApi.UnpinTuple(height);
		JlNativeApi.UnpinTuple(smax);
		err = JlObject.LoadNew(proc, 1, err, out SE);
		JlNativeApi.PostCall(proc, err);
	}


