	/// <param name="mode">Mode of the transformation. Default: "absolute"</param>
	/// <remarks>
	///   <para><b>功能说明</b>转原生算子 id 775：Store 序（句柄、index、row、column、phi、mode）与 C# 形参序完全一致；row/column 为行列方向平移量，phi 为旋转量，mode 决定变换语义，直接改写模型内对象的位姿。</para>
	///   <para><b>与实例重载的取舍</b><see cref="JlMetrologyModel.TransformMetrologyObject(JlTuple, JlTuple, JlTuple, JlTuple, JlTuple)"/>自动携带自身句柄；本静态版显式传句柄，便于对多个模型套用同一组变换量。</para>
	///   <para><b>参数取向</b>0 个 out；index 可给 "all" 或索引元组选择要搬动的对象集合。</para>
	///   <para><b>资源与坑</b>phi 的单位与 mode 各枚举（如 "absolute"）的绝对/相对语义以原生约定为准[待实测]；重复调用是否累积变换取决于 mode[待实测]。</para>
	/// </remarks>
	public static void TransformMetrologyObject(JlTuple metrologyHandle, JlTuple index, JlTuple row, JlTuple column, JlTuple phi, JlTuple mode)
	{
		IntPtr proc = JlNativeApi.PreCall(775);
		JlNativeApi.Store(proc, 0, metrologyHandle);
		JlNativeApi.Store(proc, 1, index);
		JlNativeApi.Store(proc, 2, row);
		JlNativeApi.Store(proc, 3, column);
		JlNativeApi.Store(proc, 4, phi);
		JlNativeApi.Store(proc, 5, mode);
		int procResult = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(metrologyHandle);
		JlNativeApi.UnpinTuple(index);
		JlNativeApi.UnpinTuple(row);
		JlNativeApi.UnpinTuple(column);
		JlNativeApi.UnpinTuple(phi);
		JlNativeApi.UnpinTuple(mode);
		JlNativeApi.PostCall(proc, procResult);
	}

