		JlNativeApi.Store(proc, 0, metrologyHandle);
		JlNativeApi.Store(proc, 1, index);
		JlNativeApi.Store(proc, 2, instance);
		JlNativeApi.Store(proc, 3, genParamName);
		JlNativeApi.Store(proc, 4, genParamValue);
		JlNativeApi.InitOCT(proc, 0);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(metrologyHandle);
		JlNativeApi.UnpinTuple(index);
		JlNativeApi.UnpinTuple(instance);
		JlNativeApi.UnpinTuple(genParamName);
		JlNativeApi.UnpinTuple(genParamValue);
		err = JlTuple.LoadNew(proc, 0, err, out parameter);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>取计量对象测量区域边缘点的行列坐标，并附带测量区域的矩形 XLD 轮廓，三个输出全部走 out。</summary>
	/// <param name="contours">测量区域的矩形 XLD 轮廓。</param>
	/// <param name="metrologyHandle">Handle of the metrology model.</param>
	/// <param name="index">Index of the metrology objects. Default: "all"</param>
	/// <param name="transition">选择亮/暗或暗/亮边缘。Default: "all"</param>
	/// <param name="row">测得的边缘的行坐标序列。</param>
	/// <param name="column">测得的边缘的列坐标序列。</param>
	/// <remarks>
	///   <para><b>功能说明</b>转原生算子 id 782：Store 序（句柄、index、transition）与形参一致；InitOCT 声明图标输出与控制输出两路——contours 由 JlObject.LoadNew 从图标槽装载，row/column 按 DOUBLE 从控制槽装载。给出的是拟合前采到的边缘点与测量区域轮廓；拟合结果在模型内，另用 GetMetrologyObjectResult（id 781）取。</para>
	///   <para><b>与实例重载的取舍</b><see cref="JlMetrologyModel.GetMetrologyObjectMeasures(JlTuple, string, out JlTuple, out JlTuple)"/>面向自身句柄并把轮廓装载为强类型对象；本静态版 out 出裸 JlObject 句柄，需自行判型与释放。</para>
	///   <para><b>参数取向</b>3 个 out：1 个图标（contours）+2 个 DOUBLE 元组（row、column）；contours 排在整个形参表首位。</para>
	///   <para><b>资源与坑</b>contours 是新句柄，用毕要释放（JlObject 的 Dispose 为显式接口实现，需 ((IDisposable)contours).Dispose() 或 using）；未 Apply 前无边缘可取[待实测]。</para>
	/// </remarks>
	public static void GetMetrologyObjectMeasures(out JlObject contours, JlTuple metrologyHandle, JlTuple index, JlTuple transition, out JlTuple row, out JlTuple column)
	{
		IntPtr proc = JlNativeApi.PreCall(782);
		JlNativeApi.Store(proc, 0, metrologyHandle);
		JlNativeApi.Store(proc, 1, index);
		JlNativeApi.Store(proc, 2, transition);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(metrologyHandle);
		JlNativeApi.UnpinTuple(index);
		JlNativeApi.UnpinTuple(transition);
		err = JlObject.LoadNew(proc, 1, err, out contours);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out row);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out column);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>对一幅图像执行计量模型：测量并拟合模型内全部计量对象的几何形状，结果写进模型内部，无 out。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="metrologyHandle">Handle of the metrology model.</param>
	/// <remarks>
	///   <para><b>功能说明</b>转原生算子 id 783：图像按图标输入传入、模型句柄占控制输入槽 0，测量结果全部缓存在模型句柄内部；取结果须再用 GetMetrologyObjectResult（id 781）/GetMetrologyObjectNumInstances（id 780）等。执行前应已 SetMetrologyModelImageSize（id 797）且与实际图像尺寸匹配。</para>
	///   <para><b>与实例重载的取舍</b><see cref="JlMetrologyModel.ApplyMetrologyModel(JlImage)"/>自动携带自身句柄且 image 用强类型 JlImage；本静态版 image 是裸 JlObject 句柄。JlImage 一侧没有同名封装，以图像为中心的流程也推荐以模型为主体调用。</para>
	///   <para><b>参数取向</b>0 个 out；C# 形参 image 在前、句柄在后，与原生图标/控制两通道各归其位，无需换序。</para>
	///   <para><b>资源与坑</b>image 在原生调用结束前经 GC.KeepAlive 保活，调用方不必额外处理；对同一模型连续 Apply 会覆盖上一帧结果。</para>
	/// </remarks>
	public static void ApplyMetrologyModel(JlObject image, JlTuple metrologyHandle)
	{
		IntPtr proc = JlNativeApi.PreCall(783);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, metrologyHandle);
		int procResult = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(metrologyHandle);
		JlNativeApi.PostCall(proc, procResult);
		GC.KeepAlive(image);
	}

