	/// <summary>在图像里查找 NCC 模型的匹配实例，命中位置行/列、旋转角与得分四路 DOUBLE 元组经 out 返回（原生 id 945）。</summary>
	/// <param name="image">待搜索的输入图（裸句柄）。</param>
	/// <param name="modelID">NCC 模型句柄。</param>
	/// <param name="angleStart">本次搜索的最小旋转角，弧度（须落在模型训练的角度区间内）。Default: -0.39</param>
	/// <param name="angleExtent">旋转角搜索范围，弧度。Default: 0.79</param>
	/// <param name="minScore">被接受实例的最低得分。Default: 0.8</param>
	/// <param name="numMatches">要返回的实例个数（0 表示返回所有超过 minScore 的实例）。Default: 1</param>
	/// <param name="maxOverlap">实例间允许的最大重叠率。Default: 0.5</param>
	/// <param name="subPixel">是否亚像素精化。Default: "true"</param>
	/// <param name="numLevels">匹配所用金字塔层数；给两个值时第二个为最低层。Default: 0</param>
	/// <param name="row">命中实例的行坐标（DOUBLE）。</param>
	/// <param name="column">命中实例的列坐标（DOUBLE）。</param>
	/// <param name="angle">命中实例的旋转角，弧度（DOUBLE）。</param>
	/// <param name="score">命中实例的得分（DOUBLE）。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 945：image 占图标槽 1，八个控制入参依次占控制槽 0..7（Store 钉固后逐个 UnpinTuple）；四路 out 各按 DOUBLE 装载。angleStart/angleExtent 是在模型已训练的角度区间内做二次裁剪，给到训练范围之外会搜不到；numMatches=0 返回全部达标实例，取正数时按得分从高到低截断；maxOverlap 抑制彼此重叠的重复实例。</para>
	///   <para><b>与实例重载的取舍</b>JlNCCModel 实例版 <see cref="JlNCCModel.FindNccModel(JlImage, double, double, double, int, double, string, JlTuple, out JlTuple, out JlTuple, out JlTuple, out JlTuple)"/> 以 this 为模型、image 收强类型 JlImage、numMatches 收 int、angleStart/Extent/minScore/maxOverlap 收 double；本门面把模型与图都放开为裸句柄、控制参数一律 JlTuple，数值角点若与元组重载并存须按 CS0121 规则用 double 字面量或显式 new JlTuple。</para>
	///   <para><b>参数取向</b>四路 out（row/column/angle/score）数量与签名一致，均为新建数值元组。</para>
	///   <para><b>资源与坑</b>image 由 GC.KeepAlive 保活到调用结束、不得提前释放；四路数值元组无需释放；无命中时输出为空元组 [待实测]；numLevels 传负值或两元素的最低层语义 [待实测]。</para>
	/// </remarks>
	public static void FindNccModel(JlObject image, JlTuple modelID, JlTuple angleStart, JlTuple angleExtent, JlTuple minScore, JlTuple numMatches, JlTuple maxOverlap, JlTuple subPixel, JlTuple numLevels, out JlTuple row, out JlTuple column, out JlTuple angle, out JlTuple score)
	{
		IntPtr proc = JlNativeApi.PreCall(945);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, modelID);
		JlNativeApi.Store(proc, 1, angleStart);
		JlNativeApi.Store(proc, 2, angleExtent);
		JlNativeApi.Store(proc, 3, minScore);
		JlNativeApi.Store(proc, 4, numMatches);
		JlNativeApi.Store(proc, 5, maxOverlap);
		JlNativeApi.Store(proc, 6, subPixel);
		JlNativeApi.Store(proc, 7, numLevels);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		JlNativeApi.InitOCT(proc, 3);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(modelID);
		JlNativeApi.UnpinTuple(angleStart);
		JlNativeApi.UnpinTuple(angleExtent);
		JlNativeApi.UnpinTuple(minScore);
		JlNativeApi.UnpinTuple(numMatches);
		JlNativeApi.UnpinTuple(maxOverlap);
		JlNativeApi.UnpinTuple(subPixel);
		JlNativeApi.UnpinTuple(numLevels);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out row);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out column);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out angle);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.DOUBLE, err, out score);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>就地修改 NCC 模型的若干生成参数（按参数名/参数值成对给出），无输出（原生 id 946）。</summary>
	/// <param name="modelID">待改参数的 NCC 模型句柄。</param>
