		JlNativeApi.Store(proc, 1, modelImage);
		JlNativeApi.Store(proc, 2, initialComponents);
		JlNativeApi.Store(proc, 3, trainingImages);
		JlNativeApi.Store(proc, 0, contrastLow);
		JlNativeApi.Store(proc, 1, contrastHigh);
		JlNativeApi.Store(proc, 2, minSize);
		JlNativeApi.Store(proc, 3, minScore);
		JlNativeApi.Store(proc, 4, searchRowTol);
		JlNativeApi.Store(proc, 5, searchColumnTol);
		JlNativeApi.Store(proc, 6, searchAngleTol);
		JlNativeApi.Store(proc, 7, trainingEmphasis);
		JlNativeApi.Store(proc, 8, ambiguityCriterion);
		JlNativeApi.Store(proc, 9, maxContourOverlap);
		JlNativeApi.Store(proc, 10, clusterThreshold);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 0);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(contrastLow);
		JlNativeApi.UnpinTuple(contrastHigh);
		JlNativeApi.UnpinTuple(minSize);
		JlNativeApi.UnpinTuple(minScore);
		JlNativeApi.UnpinTuple(searchRowTol);
		JlNativeApi.UnpinTuple(searchColumnTol);
		JlNativeApi.UnpinTuple(searchAngleTol);
		JlNativeApi.UnpinTuple(trainingEmphasis);
		JlNativeApi.UnpinTuple(ambiguityCriterion);
		JlNativeApi.UnpinTuple(maxContourOverlap);
		JlNativeApi.UnpinTuple(clusterThreshold);
		err = JlObject.LoadNew(proc, 1, err, out modelComponents);
		err = JlTuple.LoadNew(proc, 0, err, out componentTrainingID);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(modelImage);
		GC.KeepAlive(initialComponents);
		GC.KeepAlive(trainingImages);
