		JlNativeApi.Store(proc, 1, multiChannelImage);
		JlNativeApi.Store(proc, 0, channel);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(channel);
		err = JlObject.LoadNew(proc, 1, err, out image);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(multiChannelImage);
	}

	/// <summary>把图标数组中各图按显式位置摆进 width×height 画布拼成一张大图，结果是新句柄（原生 id 1084）。</summary>
	/// <param name="images">参与拼贴的图像（图标数组，裸句柄）。</param>
	/// <param name="tiledImage">输出：拼贴得到的新图像句柄。</param>
	/// <param name="offsetRow">输入图像在输出图像中左上角的行坐标。Default: 0</param>
	/// <param name="offsetCol">输入图像在输出图像中左上角的列坐标。Default: 0</param>
	/// <param name="row1">各输入图像中被复制部分左上角的行坐标。Default: -1</param>
	/// <param name="col1">各输入图像中被复制部分左上角的列坐标。Default: -1</param>
	/// <param name="row2">各输入图像中被复制部分右下角的行坐标。Default: -1</param>
	/// <param name="col2">各输入图像中被复制部分右下角的列坐标。Default: -1</param>
	/// <param name="width">Width of the output image. Default: 512</param>
	/// <param name="height">Height of the output image. Default: 512</param>
	/// <remarks>
	///   <para><b>功能说明</b>对应原生算子 id 1084：offsetRow/offsetCol 决定各输入图左上角落在输出图的行列位置，row1/col1/row2/col2 先裁源图子区再贴（Default -1 表示整幅复制）；画布大小即 width/height，越出画布的摆放如何裁剪 [待实测]。与 TileImages（id 1085）相反，这里全部位置由调用方显式给。</para>
	///   <para><b>与实例重载的取舍</b>实例版 <see cref="JlImage.TileImagesOffset(int, int, int, int, int, int, int, int)"/> 以调用对象为输入、直接返回结果；本静态版输入是数组句柄、结果走 out。</para>
	///   <para><b>参数取向</b>图标进槽 1；八个控制参数依次进槽 0..7（Store 钉固、调用后逐个 UnpinTuple）；输出以 InitOCT(1) 登记、经 JlObject.LoadNew 装载。</para>
	///   <para><b>资源与坑</b>tiledImage 是新句柄须 Dispose；images 由 GC.KeepAlive 保住。</para>
	/// </remarks>
	public static void TileImagesOffset(JlObject images, out JlObject tiledImage, JlTuple offsetRow, JlTuple offsetCol, JlTuple row1, JlTuple col1, JlTuple row2, JlTuple col2, JlTuple width, JlTuple height)
	{
		IntPtr proc = JlNativeApi.PreCall(1084);
		JlNativeApi.Store(proc, 1, images);
		JlNativeApi.Store(proc, 0, offsetRow);
		JlNativeApi.Store(proc, 1, offsetCol);
		JlNativeApi.Store(proc, 2, row1);
		JlNativeApi.Store(proc, 3, col1);
		JlNativeApi.Store(proc, 4, row2);
		JlNativeApi.Store(proc, 5, col2);
		JlNativeApi.Store(proc, 6, width);
		JlNativeApi.Store(proc, 7, height);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(offsetRow);
		JlNativeApi.UnpinTuple(offsetCol);
		JlNativeApi.UnpinTuple(row1);
		JlNativeApi.UnpinTuple(col1);
		JlNativeApi.UnpinTuple(row2);
		JlNativeApi.UnpinTuple(col2);
		JlNativeApi.UnpinTuple(width);
		JlNativeApi.UnpinTuple(height);
		err = JlObject.LoadNew(proc, 1, err, out tiledImage);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(images);
	}

