		JlNativeApi.UnpinTuple(width);
		JlNativeApi.UnpinTuple(numSquares);
		JlNativeApi.UnpinTuple(gridFile);
		JlNativeApi.PostCall(proc, procResult);
	}

	/// <summary>按网格点坐标在相邻格点间连出轮廓线，用于后续网格校正，轮廓以新句柄经 out 返回（原生 id 1106）。</summary>
