		JlNativeApi.UnpinTuple(distanceTransformID);
		JlNativeApi.PostCall(proc, procResult);
	}

	/// <summary>用预建的 XLD 距离变换给一组轮廓逐点量距，结果作为带"距离属性"的新轮廓句柄经 out 返回。</summary>
