		JlNativeApi.Store(proc, 1, alpha);
		JlNativeApi.Store(proc, 2, NMS);
		JlNativeApi.Store(proc, 3, low);
		JlNativeApi.Store(proc, 4, high);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(filter);
		JlNativeApi.UnpinTuple(alpha);
		JlNativeApi.UnpinTuple(NMS);
		JlNativeApi.UnpinTuple(low);
		JlNativeApi.UnpinTuple(high);
		err = JlObject.LoadNew(proc, 1, err, out imaAmp);
		err = JlObject.LoadNew(proc, 2, err, out imaDir);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}


	/// <summary>对图像求高斯拉普拉斯（LoG）响应，结果 imageLaplace 经 out 返回新句柄。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="imageLaplace">Laplace 滤波后的图像。</param>
	/// <param name="sigma">高斯平滑参数。Default: 2.0</param>
	/// <remarks>
	///   <para><b>功能说明</b>先按 sigma 高斯平滑再取拉普拉斯，可抑制噪声放大、增强零交叉斑点响应；sigma 越大只对越大的结构有响应。结果按 DOUBLE 装载含负值需自行处理。原生算子 id 1492，输出为新句柄。</para>
	///   <para><b>与实例重载的取舍</b>类型化入口见 <see cref="JlImage.LaplaceOfGauss(double)"/>（另有 <c>LaplaceOfGauss(JlTuple)</c> 版），以本对象为输入返回 JlImage；本静态版两端放开为裸 JlObject。</para>
	///   <para><b>资源与坑</b>imageLaplace 须 Dispose；image 由 GC.KeepAlive 保活，sigma 调用后 UnpinTuple。要省算力的近似版用 DiffOfGauss，有限差分拉普拉斯用 Laplace。</para>
	/// </remarks>
	public static void LaplaceOfGauss(JlObject image, out JlObject imageLaplace, JlTuple sigma)
	{
		IntPtr proc = JlNativeApi.PreCall(1492);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, sigma);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(sigma);
		err = JlObject.LoadNew(proc, 1, err, out imageLaplace);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>用两个不同 sigma 高斯之差近似 LoG 算子做斑点/边缘增强，结果 diffOfGauss 经 out 返回新句柄。</summary>
	/// <param name="image">输入图像</param>
	/// <param name="diffOfGauss">LoG 图像。</param>
	/// <param name="sigma">待逼近的 Laplace 算子的平滑参数。Default: 3.0</param>
	/// <param name="sigFactor">Ratio of the standard deviations used (Marr recommends 1.6). Default: 1.6</param>
	/// <remarks>
	///   <para><b>功能说明</b>以 G(sigma)−G(sigma/sigFactor) 差分逼近高斯拉普拉斯，sigFactor 取 Marr 推荐比值时最接近真 LoG；结果按 DOUBLE 装载可含负值。原生算子 id 1493，输出为新句柄。</para>
	///   <para><b>与实例重载的取舍</b>类型化入口见 <see cref="JlImage.DiffOfGauss(double, double)"/>，把两参钉成 double 并以本对象为输入返回 JlImage；本静态版两端放开为裸 JlObject。</para>
	///   <para><b>资源与坑</b>diffOfGauss 须 Dispose；image 由 GC.KeepAlive 保活，两参调用后 UnpinTuple。要精确 LoG 请改用 LaplaceOfGauss。</para>
	/// </remarks>
	public static void DiffOfGauss(JlObject image, out JlObject diffOfGauss, JlTuple sigma, JlTuple sigFactor)
	{
		IntPtr proc = JlNativeApi.PreCall(1493);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, sigma);
		JlNativeApi.Store(proc, 1, sigFactor);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(sigma);
		JlNativeApi.UnpinTuple(sigFactor);
		err = JlObject.LoadNew(proc, 1, err, out diffOfGauss);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}

	/// <summary>按最长延展点数闭合单像素边缘的断口，结果 closedEdges 经 out 返回新句柄。</summary>
	/// <param name="edges">包含 1 像素厚边缘的区域。</param>
	/// <param name="gradient">边缘幅值（梯度）图像。</param>
	/// <param name="closedEdges">包含闭合边缘的区域。</param>
	/// <param name="minAmplitude">最小边缘幅值。Default: 16</param>
	/// <param name="maxGapLength">边缘可延伸的最大点数。Default: 3</param>
	/// <remarks>
	///   <para><b>功能说明</b>与 CloseEdges 同类，但额外用 maxGapLength 限制每处缺口最多延展的像素数，超过则放弃闭合，可控性更强。输入 edges 须为单像素宽边缘区域。原生算子 id 1494，输出为新句柄。</para>
	///   <para><b>与实例重载的取舍</b>类型化入口见 <see cref="JlRegion.CloseEdgesLength(JlImage, int, int)"/>，以本区域为 edges、返回 JlRegion；本静态版两端放开为裸 JlObject。</para>
	///   <para><b>资源与坑</b>closedEdges 须 Dispose；edges、gradient 各有 GC.KeepAlive，两控制参数调用后 UnpinTuple。只需按幅值闭合不控长度时用 CloseEdges。</para>
	/// </remarks>
	public static void CloseEdgesLength(JlObject edges, JlObject gradient, out JlObject closedEdges, JlTuple minAmplitude, JlTuple maxGapLength)
	{
		IntPtr proc = JlNativeApi.PreCall(1494);
		JlNativeApi.Store(proc, 1, edges);
		JlNativeApi.Store(proc, 2, gradient);
		JlNativeApi.Store(proc, 0, minAmplitude);
		JlNativeApi.Store(proc, 1, maxGapLength);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(minAmplitude);
		JlNativeApi.UnpinTuple(maxGapLength);
		err = JlObject.LoadNew(proc, 1, err, out closedEdges);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(edges);
		GC.KeepAlive(gradient);
	}

	/// <summary>借助梯度幅值图闭合单像素边缘的断口，闭合后边缘 regionResult 经 out 返回新句柄。</summary>
	/// <param name="edges">包含 1 像素厚边缘的区域。</param>
	/// <param name="edgeImage">边缘幅值（梯度）图像。</param>
