	/// <param name="minAmplitude">最小边缘幅值。Default: 16</param>
	/// <remarks>
	///   <para><b>功能说明</b>沿 edges 端点在梯度图上顺梯度延伸以弥合小缺口，minAmplitude 以下不再延展（缺口越大越闭不上）。输入 edges 须为单像素宽边缘区域。原生算子 id 1495，输出为新句柄。</para>
	///   <para><b>与实例重载的取舍</b>类型化入口见 <see cref="JlRegion.CloseEdges(JlImage, int)"/>，以本区域为 edges、返回 JlRegion；本静态版两端放开为裸 JlObject。</para>
	///   <para><b>资源与坑</b>regionResult 须 Dispose；edges、edgeImage 各有 GC.KeepAlive，minAmplitude 调用后 UnpinTuple。要按长度限制延展改用 CloseEdgesLength。</para>
	/// </remarks>
	public static void CloseEdges(JlObject edges, JlObject edgeImage, out JlObject regionResult, JlTuple minAmplitude)
	{
		IntPtr proc = JlNativeApi.PreCall(1495);
		JlNativeApi.Store(proc, 1, edges);
		JlNativeApi.Store(proc, 2, edgeImage);
		JlNativeApi.Store(proc, 0, minAmplitude);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(minAmplitude);
		err = JlObject.LoadNew(proc, 1, err, out regionResult);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(edges);
		GC.KeepAlive(edgeImage);
	}

	/// <summary>检测图中直边段，用四组 out 元组分别返回各线段的起止行列坐标。</summary>
	/// <param name="image">输入图像。</param>
	/// <param name="sobelSize">Sobel 算子的掩膜尺寸。Default: 5</param>
	/// <param name="minAmplitude">最小边缘强度。Default: 32</param>
	/// <param name="maxDistance">逼近直线与原边缘的最大距离。Default: 3</param>
	/// <param name="minLength">生成线段的最小长度。Default: 10</param>
	/// <param name="beginRow">线段起点的行坐标。</param>
	/// <param name="beginCol">线段起点的列坐标。</param>
	/// <param name="endRow">线段终点的行坐标。</param>
	/// <param name="endCol">线段终点的列坐标。</param>
	/// <remarks>
	///   <para><b>功能说明</b>先用 Sobel 求边再按共线准则把边缘近似成有限直边段，minAmplitude 滤弱边、maxDistance 控拟合偏离、minLength 丢短线；四输出元组一一对应每段的端点，长度相等且按检测顺序排列（顺序不稳定时勿跨帧按下标对齐）。坐标为整数。原生算子 id 1496。</para>
	///   <para><b>与实例重载的取舍</b>类型化入口见 <see cref="JlImage.DetectEdgeSegments(int, int, int, int, out JlTuple, out JlTuple, out JlTuple, out JlTuple)"/>，把控制参数钉成 int 并以本对象为输入；本静态版 image 为裸 JlObject。</para>
	///   <para><b>资源与坑</b>四个 out JlTuple 需各自释放 [待实测]；image 由 GC.KeepAlive 保活，控制参数调用后 UnpinTuple。要像素级 XLD 直线请改用 LinesGauss/LinesColor。</para>
	/// </remarks>
	public static void DetectEdgeSegments(JlObject image, JlTuple sobelSize, JlTuple minAmplitude, JlTuple maxDistance, JlTuple minLength, out JlTuple beginRow, out JlTuple beginCol, out JlTuple endRow, out JlTuple endCol)
	{
		IntPtr proc = JlNativeApi.PreCall(1496);
		JlNativeApi.Store(proc, 1, image);
		JlNativeApi.Store(proc, 0, sobelSize);
		JlNativeApi.Store(proc, 1, minAmplitude);
		JlNativeApi.Store(proc, 2, maxDistance);
		JlNativeApi.Store(proc, 3, minLength);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		JlNativeApi.InitOCT(proc, 3);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(sobelSize);
		JlNativeApi.UnpinTuple(minAmplitude);
		JlNativeApi.UnpinTuple(maxDistance);
		JlNativeApi.UnpinTuple(minLength);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.INTEGER, err, out beginRow);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.INTEGER, err, out beginCol);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.INTEGER, err, out endRow);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.INTEGER, err, out endCol);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(image);
	}




