		JlNativeApi.Store(proc, 0, headerSize);
		JlNativeApi.Store(proc, 1, sourceWidth);
		JlNativeApi.Store(proc, 2, sourceHeight);
		JlNativeApi.Store(proc, 3, startRow);
		JlNativeApi.Store(proc, 4, startColumn);
		JlNativeApi.Store(proc, 5, destWidth);
		JlNativeApi.Store(proc, 6, destHeight);
		JlNativeApi.Store(proc, 7, pixelType);
		JlNativeApi.Store(proc, 8, bitOrder);
		JlNativeApi.Store(proc, 9, byteOrder);
		JlNativeApi.Store(proc, 10, pad);
		JlNativeApi.Store(proc, 11, index);
		JlNativeApi.Store(proc, 12, fileName);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(headerSize);
		JlNativeApi.UnpinTuple(sourceWidth);
		JlNativeApi.UnpinTuple(sourceHeight);
		JlNativeApi.UnpinTuple(startRow);
		JlNativeApi.UnpinTuple(startColumn);
		JlNativeApi.UnpinTuple(destWidth);
		JlNativeApi.UnpinTuple(destHeight);
		JlNativeApi.UnpinTuple(pixelType);
		JlNativeApi.UnpinTuple(bitOrder);
		JlNativeApi.UnpinTuple(byteOrder);
		JlNativeApi.UnpinTuple(pad);
		JlNativeApi.UnpinTuple(index);
		JlNativeApi.UnpinTuple(fileName);
		err = JlObject.LoadNew(proc, 1, err, out image);
		JlNativeApi.PostCall(proc, err);
	}

