		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out max);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out range);
		JlNativeApi.PostCall(proc, err);
