	/// <param name="height">矩形实物高（米）。</param>
	/// <param name="weightingMode">优化阶段的加权方式。Default: "nonweighted"</param>
	/// <param name="clippingFactor">剔除离群点的裁剪因子（'huber' 常取 1.0、'tukey' 常取 3.0）。Default: 2.0</param>
	/// <param name="pose">输出：矩形的 3D 位姿。</param>
	/// <param name="covPose">输出：位姿各分量的协方差。</param>
	/// <param name="error">输出：最终残差的均方根值。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 1803。已知矩形实物宽高与相机参数，从其 2D 投影解出 6 自由度位姿；width/height 必须是米制真实尺寸，给错量纲位姿随之整体错。contour 进图标槽 1、不被改写；五控制参数钉到控制槽 0..4。pose 用不指定类型 LoadNew 装载，covPose/error 按 DOUBLE 装载。</para>
	///   <para><b>与实例重载的取舍</b>Jl* 类型化实例重载未提供同名方法；本算子只能走此静态入口，contour 退化为裸句柄、worldPose 概念不涉及。</para>
	///   <para><b>参数取向</b>一进五控制三 out，out 顺序 pose/covPose/error；weightingMode 非 "nonweighted" 时 clippingFactor 才起作用。</para>
	///   <para><b>资源与坑</b>三路输出皆纯数值/字符串元组、Dispose 为空操作；contour 由 GC.KeepAlive 保命，原生调用结束前不得释放；轮廓非矩形或多轮廓时的解算歧义 [待实测]。</para>
	/// </remarks>
	public static void GetRectanglePose(JlObject contour, JlTuple cameraParam, JlTuple width, JlTuple height, JlTuple weightingMode, JlTuple clippingFactor, out JlTuple pose, out JlTuple covPose, out JlTuple error)
	{
		IntPtr proc = JlNativeApi.PreCall(1803);
		JlNativeApi.Store(proc, 1, contour);
		JlNativeApi.Store(proc, 0, cameraParam);
		JlNativeApi.Store(proc, 1, width);
		JlNativeApi.Store(proc, 2, height);
		JlNativeApi.Store(proc, 3, weightingMode);
		JlNativeApi.Store(proc, 4, clippingFactor);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(cameraParam);
		JlNativeApi.UnpinTuple(width);
		JlNativeApi.UnpinTuple(height);
		JlNativeApi.UnpinTuple(weightingMode);
		JlNativeApi.UnpinTuple(clippingFactor);
		err = JlTuple.LoadNew(proc, 0, err, out pose);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out covPose);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out error);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(contour);
	}

