		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out PX);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out PY);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out PZ);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.DOUBLE, err, out QX);
		err = JlTuple.LoadNew(proc, 4, JlTupleType.DOUBLE, err, out QY);
		err = JlTuple.LoadNew(proc, 5, JlTupleType.DOUBLE, err, out QZ);
		JlNativeApi.PostCall(proc, err);
	}



	/// <summary>用内部相机参数把一组 3D 点投影到像素坐标，行列两路各经 out 以 DOUBLE 元组返回。</summary>
	/// <param name="x">待投影点的相机系 X 坐标。</param>
	/// <param name="y">待投影点的相机系 Y 坐标。</param>
	/// <param name="z">待投影点的相机系 Z 坐标。</param>
	/// <param name="cameraParam">内部相机参数（标定得到的参数元组）。</param>
	/// <param name="row">输出：投影点行坐标（像素，可为亚像素值）。</param>
	/// <param name="column">输出：投影点列坐标（像素）。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 1827。纯前向投影：x/y/z/cameraParam 按声明序钉到控制槽 0..3，两路输出 InitOCT(0/1) 后经 JlTuple.LoadNew(DOUBLE) 装载；相机系约定 X 向右、Y 向下、Z 沿光轴向前，Z 非正（点在相机背后）的点结果无意义 [待实测：原生是否报错]。</para>
	///   <para><b>与 GetLineOfSight 的对偶</b>本算子由 3D 求 2D 像素；反方向（给像素求射线）走 GetLineOfSight。二者一个丢深度、一个丢射线方向，不能互相替代。</para>
	///   <para><b>何时用静态版</b>投影族在本库以 JlTuple 进 JlTuple 出，Jl* 类型化实例重载未提供同名方法；cameraParam 是裸参数元组而非已删除的相机参数对象类型。</para>
	///   <para><b>参数取向</b>三输入点坐标加一参数元组共四路入、两路 out，全部 DOUBLE 装载、逐元素等长对应。</para>
	///   <para><b>资源与坑</b>纯数值元组无需 Dispose；四路入参调用后逐个 UnpinTuple；点坐标与 cameraParam 长度不匹配时的配对规则 [待实测]。</para>
	///   <code>
	///   JlOperatorSet.Project3dPoint(new double[] { 10.0, 20.0 }, new double[] { 0.0, 5.0 }, new double[] { 500.0, 500.0 }, new JlTuple(), out JlTuple row, out JlTuple col);
	///   </code>
	/// </remarks>
	public static void Project3dPoint(JlTuple x, JlTuple y, JlTuple z, JlTuple cameraParam, out JlTuple row, out JlTuple column)
	{
		IntPtr proc = JlNativeApi.PreCall(1827);
		JlNativeApi.Store(proc, 0, x);
		JlNativeApi.Store(proc, 1, y);
		JlNativeApi.Store(proc, 2, z);
		JlNativeApi.Store(proc, 3, cameraParam);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(x);
		JlNativeApi.UnpinTuple(y);
		JlNativeApi.UnpinTuple(z);
		JlNativeApi.UnpinTuple(cameraParam);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out row);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out column);
		JlNativeApi.PostCall(proc, err);
	}






	/// <summary>把序列化项句柄还原为 3D 位姿，位姿经 out 以新建 JlTuple 交回。</summary>
