	///   JlOperatorSet.CreatePose(0.1, 0.1, 20.0, 0.0, 0.0, 0.0, "Rp+T", "gba", "point", out JlTuple pose);
	///   JlOperatorSet.SerializePose(pose, out JlTuple serHandle);
