		GC.KeepAlive(image);
	}



















	/// <summary>求两条轮廓间的最近距离及各自的最近点坐标，五路输出均为按 DOUBLE 装载的新建元组。</summary>
	/// <param name="contour1">第一条输入轮廓。</param>
	/// <param name="contour2">第二条输入轮廓。</param>
	/// <param name="mode">距离度量模式。Default: "fast_point_to_segment"</param>
	/// <param name="distanceMin">两轮廓间的最近距离（像素）。</param>
	/// <param name="row1">Contour1 上最近点行坐标。</param>
	/// <param name="column1">Contour1 上最近点列坐标。</param>
	/// <param name="row2">Contour2 上最近点行坐标。</param>
	/// <param name="column2">Contour2 上最近点列坐标。</param>
	/// <remarks>
	///   <para><b>功能说明</b>原生算子 id 1996。除距离外同时给出两切点，可直接接量测或画箭头；默认模式把点间距离放宽为点到线段距离做快速近似，对折线化轮廓可能略低估真实点距 [待实测：与逐点对模式的误差]。</para>
	///   <para><b>与实例重载的取舍</b>实例版见 <see cref="JlXLDCont.DistanceCcMinPoints(JlXLDCont, JlTuple, out JlTuple, out JlTuple, out JlTuple, out JlTuple)"/>（距离作返回值）与标量版 <see cref="JlXLDCont.DistanceCcMinPoints(JlXLDCont, string, out double, out double, out double, out double)"/>：容器强类型；标量版每路只取第一值，多轮廓场景请走本静态版或元组版。</para>
	///   <para><b>参数取向</b>iconic 输入占槽 1、2；唯一控制参数 mode 在槽 0；五路输出按声明序 DOUBLE 装载。输入轮廓为多条时两两配对规则 [待实测]。</para>
	///   <para><b>资源与坑</b>两条轮廓均由 GC.KeepAlive 保活，原生调用结束前不得释放；纯数值元组无需 Dispose。</para>
	/// </remarks>
	public static void DistanceCcMinPoints(JlObject contour1, JlObject contour2, JlTuple mode, out JlTuple distanceMin, out JlTuple row1, out JlTuple column1, out JlTuple row2, out JlTuple column2)
	{
		IntPtr proc = JlNativeApi.PreCall(1996);
		JlNativeApi.Store(proc, 1, contour1);
		JlNativeApi.Store(proc, 2, contour2);
		JlNativeApi.Store(proc, 0, mode);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		JlNativeApi.InitOCT(proc, 3);
		JlNativeApi.InitOCT(proc, 4);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(mode);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out distanceMin);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out row1);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out column1);
		err = JlTuple.LoadNew(proc, 3, JlTupleType.DOUBLE, err, out row2);
		err = JlTuple.LoadNew(proc, 4, JlTupleType.DOUBLE, err, out column2);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(contour1);
		GC.KeepAlive(contour2);
	}





