		err = JlTuple.LoadNew(proc, 0, JlTupleType.INTEGER, err, out distance);
		JlNativeApi.PostCall(proc, err);
	}















	/// <summary>由非规则分布的对应点对拟合坐标映射并生成图像映射图（map），out 为新建句柄、用毕需 Dispose。</summary>
