	/// <param name="mapHeight">生成映射图的高度（像素）。</param>
	/// <param name="method">生成映射图所用的拟合方法。Default: "thin_plate_spline"</param>
	/// <param name="mapType">生成映射图的类型（精度档）。Default: "coord_map_sub_pix"</param>
