		JlNativeApi.Store(proc, 2, row2);
		JlNativeApi.Store(proc, 3, column2);
		JlNativeApi.Store(proc, 4, imageWidth);
		JlNativeApi.Store(proc, 5, imageHeight);
		JlNativeApi.Store(proc, 6, mapWidth);
		JlNativeApi.Store(proc, 7, mapHeight);
		JlNativeApi.Store(proc, 8, method);
		JlNativeApi.Store(proc, 9, mapType);
		JlNativeApi.Store(proc, 10, genParamName);
		JlNativeApi.Store(proc, 11, genParamValue);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(row1);
		JlNativeApi.UnpinTuple(column1);
		JlNativeApi.UnpinTuple(row2);
		JlNativeApi.UnpinTuple(column2);
